 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.CsvSource({"true,601","false,601","true,602","false,602"})
 void crossWarehouseMultiProductEntriesDoNotInvertUnitUsageAndValuationLocks(boolean previouslyUsed,long secondBook)throws Exception{
  seed("INSERT INTO md_product(id,product_code,name,base_unit) VALUES(502,'SKU2','Product2','PCS')");seed("INSERT INTO md_product_unit(product_id,unit,factor_to_base) VALUES(502,'PCS',1)");seed("INSERT INTO md_country_sku(country_id,product_id,status) VALUES(101,502,'ENABLED')");
  if(previouslyUsed)seed("INSERT INTO md_product_unit_used(product_id,unit) VALUES(501,'PCS'),(502,'PCS')");
  if(secondBook!=601){seed("INSERT INTO fin_book(id,country_id,entity_id,code,name,base_currency,status) VALUES(602,101,301,'B2','Book2','MXN','ACTIVE')");seed("INSERT INTO fin_period(country_id,book_id,fiscal_year,period_no,start_date,end_date,status) VALUES(101,602,2026,10,'2026-10-01','2026-10-31','OPEN')");seed("INSERT INTO cst_method_config(country_id,book_id,method,effective_from) VALUES(101,602,'FIFO','2026-10-01')");}
  var firstEntered=new java.util.concurrent.CountDownLatch(1);var secondEntered=new java.util.concurrent.CountDownLatch(1);var continueFirst=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);String subject="unit-usage-race-"+UUID.randomUUID();
  java.util.function.BiFunction<Long,Long,InventoryApi.Inbound> input=(warehouse,product)->new InventoryApi.Inbound(warehouse==402?secondBook:601,warehouse,product,BigDecimal.ONE,BigDecimal.ZERO,BigDecimal.ZERO,new InventoryApi.Source("LGS_RECEIPT",800,warehouse*10+product,"UNIT-RACE"),LocalDate.of(2026,10,15),null,null,null);
  try{
   var first=pool.submit(()->inCountry(101,()->{authorization.authorize(actor);writer.inbound(actor,input.apply(401L,501L));firstEntered.countDown();try{if(!continueFirst.await(15,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("Second writer did not reach the valuation gate");}catch(InterruptedException e){throw new IllegalStateException(e);}writer.inbound(actor,input.apply(401L,502L));return true;}));
   assertThat(firstEntered.await(15,java.util.concurrent.TimeUnit.SECONDS)).isTrue();
   var second=pool.submit(()->inCountry(101,()->{authorization.authorize(actor);jdbc.queryForObject("SELECT set_config('application_name',?,true)",String.class,subject);jdbc.execute("SET LOCAL lock_timeout='8s'");writer.inbound(actor,input.apply(402L,502L));if(secondBook!=601){secondEntered.countDown();try{if(!continueFirst.await(15,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("First writer did not complete the opposite product order");}catch(InterruptedException e){throw new IllegalStateException(e);}writer.inbound(actor,input.apply(402L,501L));}return true;}));
   if(secondBook==601){long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(8);boolean waiting=false;
    while(System.nanoTime()<deadline){waiting=owner.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE application_name=? AND wait_event_type='Lock' AND query LIKE '%pg_advisory_xact_lock%')",Boolean.class,subject);if(waiting)break;Thread.sleep(10);}
    assertThat(waiting).as("second native writer waits at the existing valuation gate").isTrue();
   }else assertThat(secondEntered.await(15,java.util.concurrent.TimeUnit.SECONDS)).as("both books hold their first native entry before opposite products").isTrue();continueFirst.countDown();
   assertThat(first.get(15,java.util.concurrent.TimeUnit.SECONDS)).isTrue();assertThat(second.get(15,java.util.concurrent.TimeUnit.SECONDS)).isTrue();
   int expected=secondBook==601?3:4;for(String table:List.of("inv_batch","inv_stock_txn","cst_inbound_cost"))assertThat(owner.queryForObject("SELECT count(*) FROM "+table,Integer.class)).as(table).isEqualTo(expected);
   assertThat(owner.queryForObject("SELECT sum(on_hand_qty) FROM inv_stock_summary",BigDecimal.class)).isEqualByComparingTo(String.valueOf(expected));assertThat(owner.queryForList("SELECT product_id FROM md_product_unit_used WHERE unit='PCS' ORDER BY product_id",Long.class)).containsExactly(501L,502L);
  }finally{continueFirst.countDown();pool.shutdownNow();}
 }
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"OPENING_STOCK","RECEIPT"})
 void firstNativeStockEntryLocksItsBaseUnitOnlyWhenTheTransactionCommits(String source){
  seed("UPDATE sys_user SET is_platform_admin=true WHERE id=201");
  Runnable enter;
  if(source.equals("OPENING_STOCK")){var batch=imports.create(actor,Map.of("importType","OPENING_STOCK","cutoffDate","2026-10-15","rows",List.of(opening("UNIT-OPEN","3.25"))));assertThat(batch.get("status")).isEqualTo("VALIDATED");enter=()->imports.confirm(actor,((Number)batch.get("id")).longValue(),UUID.randomUUID().toString());}
  else enter=()->inCountry(101,()->writer.inbound(actor,new InventoryApi.Inbound(601,401,501,new BigDecimal("2"),BigDecimal.ZERO,BigDecimal.ZERO,new InventoryApi.Source("LGS_RECEIPT",800,901,"UNIT-RECEIPT"),LocalDate.of(2026,10,15),null,null,null)));
  assertThat(owner.queryForObject("SELECT count(*) FROM md_product_unit_used",Integer.class)).isZero();
  owner.execute("CREATE FUNCTION unit_usage_rollback_test() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'EXPECTED_UNIT_ROLLBACK';END $$");owner.execute("CREATE TRIGGER unit_usage_rollback_test BEFORE INSERT ON cst_inbound_cost FOR EACH ROW EXECUTE FUNCTION unit_usage_rollback_test()");
  try{assertThatThrownBy(enter::run).hasStackTraceContaining("EXPECTED_UNIT_ROLLBACK");for(String table:List.of("md_product_unit_used","inv_batch","inv_stock_txn","cst_inbound_cost","sys_import_source"))assertThat(owner.queryForObject("SELECT count(*) FROM "+table,Integer.class)).as(table).isZero();}finally{owner.execute("DROP TRIGGER unit_usage_rollback_test ON cst_inbound_cost");owner.execute("DROP FUNCTION unit_usage_rollback_test()");}
  owner.execute("CREATE FUNCTION unit_usage_commit_fail_test() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'EXPECTED_USAGE_COMMIT_ROLLBACK';END $$");owner.execute("CREATE TRIGGER unit_usage_commit_fail_test BEFORE INSERT ON md_product_unit_used FOR EACH ROW EXECUTE FUNCTION unit_usage_commit_fail_test()");
  try{assertThatThrownBy(enter::run).hasStackTraceContaining("EXPECTED_USAGE_COMMIT_ROLLBACK");for(String table:List.of("md_product_unit_used","inv_batch","inv_stock_txn","cst_inbound_cost","sys_import_source"))assertThat(owner.queryForObject("SELECT count(*) FROM "+table,Integer.class)).as("commit failure "+table).isZero();}finally{owner.execute("DROP TRIGGER unit_usage_commit_fail_test ON md_product_unit_used");owner.execute("DROP FUNCTION unit_usage_commit_fail_test()");}
  enter.run();
  assertThatThrownBy(()->products.saveProduct(actor,501L,Map.of("productCode","SKU","name","Product","baseUnit","BOX","version",owner.queryForObject("SELECT version FROM md_product WHERE id=501",Long.class)),UUID.randomUUID().toString())).extracting("code").isEqualTo("MD_REFERENCED");
  assertThat(owner.queryForObject("SELECT base_unit FROM md_product WHERE id=501",String.class)).isEqualTo("PCS");assertThat(owner.queryForList("SELECT unit FROM md_product_unit_used WHERE product_id=501",String.class)).containsExactly("PCS");for(String table:List.of("pur_order","sal_order"))assertThat(owner.queryForObject("SELECT count(*) FROM "+table,Integer.class)).isZero();
 }
