 @Test void completedLegacyOpeningSourceCannotBeImportedUnderAnotherCutoff(){
  String oldKey="2026-10-15:401:501:LEGACY";var json=new com.hs.jxc.common.api.JsonCodec();
  seed("INSERT INTO sys_import_batch(id,country_id,import_type,file_sha256,content_sha256,hash_basis,cutoff_date,status,requested_by,total_rows,valid_rows,confirmed_by,confirmed_at) VALUES(9001,101,'OPENING_STOCK',repeat('c',64),repeat('d',64),'CANONICAL_ROWS','2026-10-15','COMPLETED',201,1,1,201,clock_timestamp())");
  seed("INSERT INTO inv_batch(id,country_id,book_id,product_id,batch_no,source_type,source_id,source_line_id,first_inbound_date,opening_batch_no,opening_warehouse_id,cutoff_date) VALUES(9003,101,601,501,'LEGACY-NATIVE','OPENING_STOCK',9001,9002,'2026-10-15','LEGACY',401,'2026-10-15')");
  seed("INSERT INTO sys_import_row(id,country_id,batch_id,row_no,raw,normalized,source_key,target_type,target_id) VALUES(9002,101,9001,1,?::jsonb,?::jsonb,?,'INV_BATCH',9003)",json.write(opening("LEGACY","3.25")),json.write(Map.of("bookId",601,"warehouseId",401,"productId",501,"qty",2,"unitCost",3.25,"batchNo","LEGACY","refNo","LEGACY","sourceDate","2026-10-15")),oldKey);
  seed("INSERT INTO sys_import_source(country_id,import_type,source_key,row_id) VALUES(101,'OPENING_STOCK',?,9002)",oldKey);
  var retry=imports.create(actor,Map.of("importType","OPENING_STOCK","cutoffDate","2026-10-16","rows",List.of(opening("LEGACY","3.25"))));
  assertThat(retry.get("status")).isEqualTo("VALIDATION_FAILED");
  assertThat((List<Map<String,Object>>)retry.get("errors")).extracting(e->e.get("code")).containsExactly("SYS_IMPORT_REFERENCE_EXISTS");
  assertThat(owner.queryForObject("SELECT source_key FROM sys_import_source",String.class)).isEqualTo(oldKey);
  assertThat(imports.detail(actor,9001)).containsEntry("status","COMPLETED");
  assertThat(owner.queryForObject("SELECT count(*) FROM inv_batch",Integer.class)).isEqualTo(1);
  assertThat(owner.queryForObject("SELECT count(*) FROM cst_inbound_cost",Integer.class)).isZero();
 }
 @Autowired com.hs.jxc.inv.service.InventoryImportHandler openingHandler;
 @Test void pendingLegacySourceCanBeCancelledAndRevalidatedFromTheSameOriginalFile(){
  var raw=opening("PENDING-KEY","3.25");var json=new com.hs.jxc.common.api.JsonCodec();String source=json.write(List.of(raw)),fileHash=com.hs.jxc.common.api.Digests.sha256(source),oldKey="2026-10-15:401:501:PENDING-KEY";
  var reviewed=inCountry(101,()->openingHandler.validate(authorization.authorize(actor),"OPENING_STOCK",LocalDate.of(2026,10,15),1,raw));
  String contentHash=com.hs.jxc.common.api.Digests.sha256(json.write(com.hs.jxc.common.idempotency.IdempotencyExecutor.canonical(Map.of("type","OPENING_STOCK","cutoffDate","2026-10-15","rows",List.of(raw)))));
  seed("INSERT INTO sys_import_batch(id,country_id,import_type,file_sha256,source_file_text,content_sha256,hash_basis,cutoff_date,status,requested_by,total_rows,valid_rows) VALUES(9101,101,'OPENING_STOCK',?,?,?,'SOURCE_BYTES','2026-10-15','VALIDATED',201,1,1)",fileHash,source,contentHash);
  seed("INSERT INTO sys_import_row(id,country_id,batch_id,row_no,raw,normalized,source_key) VALUES(9102,101,9101,1,?::jsonb,?::jsonb,?)",json.write(raw),json.write(reviewed.values()),oldKey);
  assertThatThrownBy(()->imports.confirm(actor,9101,UUID.randomUUID().toString())).extracting("code").isEqualTo("SYS_IMPORT_STALE");
  assertThat(owner.queryForObject("SELECT count(*) FROM sys_import_source",Integer.class)).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM inv_batch",Integer.class)).isZero();
  assertThat(imports.cancel(actor,9101)).containsEntry("status","CANCELLED");
  var retry=imports.create(actor,Map.of("importType","OPENING_STOCK","cutoffDate","2026-10-15","sourceFileText",source));
  assertThat(retry).containsEntry("status","VALIDATED").containsEntry("fileSha256",fileHash).containsEntry("attemptNo",2).containsEntry("previousBatchId",9101L);
  assertThat(imports.confirm(actor,((Number)retry.get("id")).longValue(),UUID.randomUUID().toString())).containsEntry("status","COMPLETED");
  assertThat(imports.detail(actor,9101)).containsEntry("status","CANCELLED").containsEntry("sourceFileText",source);
  assertThat(owner.queryForObject("SELECT source_key FROM sys_import_row WHERE id=9102",String.class)).isEqualTo(oldKey);
  assertThat(owner.queryForObject("SELECT source_key FROM sys_import_source",String.class)).isEqualTo("601:401:501:PENDING-KEY");
  assertThat(owner.queryForObject("SELECT sum(on_hand_qty) FROM inv_stock_summary",BigDecimal.class)).isEqualByComparingTo("2");
 }
 @Test void concurrentOpeningConfirmationsWithDifferentCutoffsCannotDuplicateInventory()throws Exception{
  var batches=new ArrayList<Long>();for(String cutoff:List.of("2026-10-15","2026-10-16")){var batch=imports.create(actor,Map.of("importType","OPENING_STOCK","cutoffDate",cutoff,"rows",List.of(opening("CROSS-CUTOFF","3.25"))));assertThat(batch.get("status")).isEqualTo("VALIDATED");batches.add(((Number)batch.get("id")).longValue());}
  var start=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);
  try{var results=new ArrayList<java.util.concurrent.Future<Boolean>>();for(long batch:batches)results.add(pool.submit(()->{start.await();try{imports.confirm(actor,batch,UUID.randomUUID().toString());return true;}catch(com.hs.jxc.common.api.ApiException e){assertThat(e.getCode()).isIn("SYS_IMPORT_REFERENCE_EXISTS","SYS_IMPORT_DUPLICATE_SOURCE");return false;}}));start.countDown();int successes=0;for(var result:results)if(result.get(20,java.util.concurrent.TimeUnit.SECONDS))successes++;assertThat(successes).isEqualTo(1);
   assertThat(owner.queryForObject("SELECT count(*) FROM inv_batch",Integer.class)).isEqualTo(1);
   assertThat(owner.queryForObject("SELECT sum(on_hand_qty) FROM inv_stock_summary",BigDecimal.class)).isEqualByComparingTo("2");
   assertThat(owner.queryForObject("SELECT sum(base_purchase_amount) FROM cst_inbound_cost",BigDecimal.class)).isEqualByComparingTo("6.5");
   assertThat(owner.queryForObject("SELECT source_key FROM sys_import_source",String.class)).isEqualTo("601:401:501:CROSS-CUTOFF");
   assertThat(owner.queryForObject("SELECT count(*) FROM sys_import_batch WHERE status='COMPLETED'",Integer.class)).isEqualTo(1);
   assertThat(owner.queryForObject("SELECT count(*) FROM sys_import_row WHERE target_id IS NOT NULL",Integer.class)).isEqualTo(1);
  }finally{pool.shutdownNow();}
 }
