 private void seedDemand(){
  seed("INSERT INTO md_customer(id,country_id,code,name) VALUES(801,101,'C','Customer')");
  for(int i=0;i<3;i++)seed("INSERT INTO sal_order(id,country_id,book_id,entity_id,customer_id,doc_no,order_date,currency,payment_type,entered_by,approval_status,approved_at) VALUES(?,101,601,301,801,?,'2026-10-01','MXN','CASH',201,?,'2026-10-16 02:00:00+00')",901+i,"SO-"+i,"DRAFT");
  seed("WITH lines AS (INSERT INTO sal_order_line(id,country_id,book_id,order_id,product_id,line_no,unit,factor,qty,base_qty,price,price_source,line_amount,cancelled_qty,outbound_qty) VALUES(911,101,601,901,501,1,'PCS',1,10,10,1,'MANUAL',10,2,1),(912,101,601,901,501,2,'PCS',1,3,3,1,'MANUAL',3,0,0),(913,101,601,902,501,1,'PCS',1,100,100,1,'MANUAL',100,0,0),(914,101,601,903,501,1,'PCS',1,50,50,1,'MANUAL',50,50,0) RETURNING id) INSERT INTO sal_order_alloc(country_id,book_id,order_id,order_line_id,warehouse_id,alloc_qty,cancelled_qty,outbound_qty) SELECT 101,601,v.order_id,v.line_id,v.warehouse_id,v.qty,v.cancelled,v.outbound FROM (VALUES(901,911,401,6,2,1),(901,911,402,4,0,0),(901,912,401,3,0,0),(902,913,401,100,0,0),(903,914,401,50,50,0)) v(order_id,line_id,warehouse_id,qty,cancelled,outbound) JOIN lines ON lines.id=v.line_id");
  seed("UPDATE sal_order SET approval_status=CASE WHEN id=902 THEN 'PENDING' ELSE 'APPROVED' END");
 }
