 @Test void replenishmentUsesNativeTransferReceiptsAndReadOnlyLists(){inventory.saveLimits(actor,Map.of("items",List.of(Map.of("warehouseId",401,"productId",501,"minQty",4,"maxQty",10,"alertEnabled",true))),UUID.randomUUID().toString());var suggested=(Map<?,?>)replenishments.suggest(actor,UUID.randomUUID().toString());assertThat(((Number)suggested.get("created")).intValue()).isEqualTo(2);assertThat(((Map<?,?>)replenishments.suggest(actor,UUID.randomUUID().toString())).get("created")).isEqualTo(0);assertThat(owner.queryForObject("SELECT count(*) FROM pur_order",Integer.class)).isZero();long request=owner.queryForObject("SELECT min(id) FROM inv_replenish",Long.class);replenishments.action(actor,request,"decide",Map.of("decidedSource","TRANSFER"),UUID.randomUUID().toString());seed("INSERT INTO wf_doc_type_config(country_id,doc_type,approval_required) VALUES(101,'TRANSFER',false)");inCountry(101,()->writer.inbound(actor,new InventoryApi.Inbound(601,402,501,BigDecimal.TEN,BigDecimal.ZERO,BigDecimal.ZERO,new InventoryApi.Source("LGS_RECEIPT",800,901,"SOURCE"),LocalDate.of(2026,10,15),null,null,null)));var transfer=inventory.create(actor,"transfer",Map.of("fromWarehouseId",402,"toWarehouseId",401,"plannedDate","2026-10-15","submit",true,"lines",List.of(Map.of("productId",501,"qty",8))),UUID.randomUUID().toString());long tid=((Number)transfer.get("id")).longValue();replenishments.action(actor,request,"link",Map.of("execDocType","INV_TRANSFER","execDocId",tid),UUID.randomUUID().toString());var shipped=inventory.action(actor,"transfer",tid,"ship",Map.of(),UUID.randomUUID().toString());long line=((Number)((Map<?,?>)((List<?>)shipped.get("lines")).getFirst()).get("id")).longValue();inventory.action(actor,"transfer",tid,"receive",Map.of("lines",List.of(Map.of("lineId",line,"qty",3))),UUID.randomUUID().toString());int audits=owner.queryForObject("SELECT count(*) FROM sys_audit_log",Integer.class);var listed=(Map<?,?>)replenishments.list(actor);var item=((List<Map<String,Object>>)(List<?>)listed.get("records")).stream().filter(r->((Number)r.get("id")).longValue()==request).findFirst().orElseThrow();assertThat(item.get("status")).isEqualTo("PARTIAL");assertThat((BigDecimal)item.get("fulfilledQty")).isEqualByComparingTo("3");assertThat(owner.queryForObject("SELECT count(*) FROM sys_audit_log",Integer.class)).isEqualTo(audits);replenishments.action(actor,request,"close",Map.of("note","verified"),UUID.randomUUID().toString());assertThat(owner.queryForObject("SELECT status FROM inv_replenish WHERE id=?",String.class,request)).isEqualTo("CLOSED");}
